window.RTLBenchLSData.register("assets/d356016c35923572775441fd8f80dfe19c83eae3a1bec9f533d0588a4a1ca0ff.txt","module origen_178419(\n    input ready,\n    input clk,\n    input reset,\n    input [7:0] datain,\n    output reg [7:0] dataout\n);\n\nreg [1:0] estado, est_sig;\n\nalways @(posedge clk or posedge reset) begin\n    if (reset)\n        estado <= 2'b00;\n    else\n        estado <= est_sig;\nend\n\nalways @* begin\n    case (estado)\n        2'b00: begin\n            if (ready)\n                est_sig = 2'b01;\n            else\n                est_sig = 2'b00;\n        end\n        2'b01: begin\n            if (datain == 8'hf0)\n                est_sig = 2'b10;\n            else\n                est_sig = 2'b00;\n        end\n        2'b10: begin\n            if (ready)\n                est_sig = 2'b00;\n            else\n                est_sig = 2'b10;\n        end\n        2'b11: begin\n            est_sig = 2'b00;\n        end\n        default: begin\n            est_sig = 2'b00;\n        end\n    endcase\nend\n\nalways @(posedge clk or posedge reset) begin\n    if (reset)\n        dataout <= 8'd0;\n    else if (estado == 2'b10 && ready)\n        dataout <= datain;\nend\n\nendmodule");
